    static func reason(_ code:String,_ language:String)->String {
        let key:String
        switch code {
        case "EXCLUDED_OR_UNCOVERED","NOT_OBSERVED":key="reasonUnexamined"
        case "R51_DOCUMENT_CONTENT_LIMIT_EXCEEDED":key="reasonTooLarge"
        case "SOURCE_BYTES_NOT_SUPPLIED","MAPPING_SOURCE_NOT_COMPARABLE":key="reasonMetadata"
        case "EXISTING_IDENTITY_CONFLICT","IDENTITY_REFERENCE_CONFLICT":key="reasonIdentity"
        case "CANONICAL_AND_MAPPING_DOCUMENT_CONFLICT":key="reasonMapping"
        default:key="INSUFFICIENT_INFORMATION"
        }
        return text(key,language)
    }
    static func text(_ key:String,_ language:String)->String {let index=["en","nl","de","fr","es"].firstIndex(of:language) ?? 0;return values[key]?[index] ?? ""}
